<section class="page-heading"><span class="eyebrow">Administration</span><h1>Verification queue</h1><p>Review these records against authoritative sources before marking them verified.</p></section><?php if(!$schemes): ?><div class="empty-state"><h2>Queue is clear</h2><p>No unverified or pending-review schemes are recorded.</p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Scheme</th><th>Publication</th><th>Review status</th><th>Last verified</th><th>Updated</th><th></th></tr></thead><tbody><?php foreach($schemes as $scheme): ?><tr><td><?=e($scheme['title'])?></td><td><?=e($scheme['status'])?></td><td><?=e(str_replace('_',' ',$scheme['verification_status']))?></td><td><?=e($scheme['last_verified_at']?:'Not recorded')?></td><td><?=e($scheme['updated_at'])?></td><td><a href="<?=e(url('admin_scheme',['id'=>$scheme['id']]))?>">Review record</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><p class="mt"><a href="<?=e(url('admin'))?>">← Admin dashboard</a></p>
